const assert = require('node:assert/strict');
const { Ledger } = require('../.build/ledger');
const { PaymentService } = require('../.build/service');
const { Transient } = require('../.build/transport');

async function main() {
  const ledger = new Ledger();
  const receipts = [];
  const service = new PaymentService(ledger, {
    acknowledge: async r => { receipts.push(r); }
  });
  const first = await service.pay('shop', 'sale', 123);
  assert.deepEqual(first, { id: 1, tenant: 'shop', key: 'sale', cents: 123 });
  assert.equal(ledger.entries.length, 1);
  assert.equal(receipts.length, 1);
  const repeated = await Promise.all(Array.from({ length: 10 }, () => service.pay('shop', 'sale', 123)));
  repeated.forEach(r => assert.strictEqual(r, first));
  assert.equal(ledger.entries.length, 1);
  await assert.rejects(service.pay('shop', 'sale', 124), { message: 'key conflict' });
  assert.equal(receipts.length, 11);
  assert.equal(ledger.entries.length, 1);
  await service.pay('other', 'sale', 124);
  await service.pay('shop', 'other', 124);
  assert.equal(ledger.entries.length, 3);

  const concurrentLedger = new Ledger();
  const concurrent = await Promise.all(Array.from({ length: 10 }, () => concurrentLedger.apply('t', 'k', 1)));
  concurrent.forEach(r => assert.strictEqual(r, concurrent[0]));
  assert.equal(concurrentLedger.entries.length, 1);
  await assert.rejects(concurrentLedger.apply('t', 'k', 2), { message: 'key conflict' });
  // Delimiter-like keys must not collide across tenants.
  await concurrentLedger.apply('a:b', 'c', 1);
  await concurrentLedger.apply('a', 'b:c', 2);
  assert.equal(concurrentLedger.entries.length, 3);

  for (const attempts of [1, 3, 5]) {
    const retryLedger = new Ledger();
    const sent = [];
    const failures = Array.from({ length: attempts }, (_, i) => new Transient(`failure ${i}`));
    const retryService = new PaymentService(retryLedger, {
      acknowledge: async r => { sent.push(r); throw failures[sent.length - 1]; }
    });
    await assert.rejects(retryService.pay('t', 'k', 10, attempts), error => error === failures[attempts - 1]);
    assert.equal(sent.length, attempts);
    assert.equal(retryLedger.entries.length, 1);
    sent.forEach(r => assert.strictEqual(r, retryLedger.entries[0]));
  }
  const successLedger = new Ledger();
  const sent = [];
  const eventual = new PaymentService(successLedger, {
    acknowledge: async r => { sent.push(r); if (sent.length < 3) throw new Transient(); }
  });
  const result = await eventual.pay('t', 'k', 10);
  assert.equal(sent.length, 3);
  sent.forEach(r => assert.strictEqual(r, result));
  assert.equal(successLedger.entries.length, 1);

  const permanent = new Error('permanent');
  let calls = 0;
  const failing = new PaymentService(new Ledger(), {
    acknowledge: async () => { calls++; throw permanent; }
  });
  await assert.rejects(failing.pay('t', 'k', 1), error => error === permanent);
  assert.equal(calls, 1);

  let actions = 0;
  const validating = new PaymentService({ apply: async () => { actions++; } }, {
    acknowledge: async () => { actions++; }
  });
  const invalid = [
    ['', 'k', 1, 3], ['t', '', 1, 3], [null, 'k', 1, 3], ['t', 1, 1, 3],
    ...[0, -1, 1.5, NaN, Infinity].map(c => ['t', 'k', c, 3]),
    ...[0, -1, 6, 1.5, NaN, Infinity, '3', null].map(a => ['t', 'k', 1, a])
  ];
  for (const args of invalid) {
    await assert.rejects(validating.pay(...args), { message: 'invalid payment' });
  }
  assert.equal(actions, 0);
  const invalidLedger = new Ledger();
  for (const args of invalid.slice(0, 9)) {
    await assert.rejects(invalidLedger.apply(...args), { message: 'invalid payment' });
  }
  assert.equal(invalidLedger.entries.length, 0);
}
module.exports = main();
